CREATE TABLE "USERS" (
    "ID" NUMBER DEFAULT "TESTSCHEMA"."ISEQ$$_0000002".nextval NOT NULL,
    "USERNAME" VARCHAR2(50 BYTE) NOT NULL,
    "EMAIL" VARCHAR2(100 BYTE) NOT NULL,
    "CREATED_AT" TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE "USERS" ADD CONSTRAINT "SYS_C0000002" PRIMARY KEY (ID);
CREATE INDEX "IDX_USERNAME" ON "USERS" ("USERNAME" ASC);
CREATE UNIQUE INDEX "UK_EMAIL" ON "USERS" ("EMAIL" ASC);

CREATE TABLE "POSTS" (
    "ID" NUMBER DEFAULT "TESTSCHEMA"."ISEQ$$_0000001".nextval NOT NULL,
    "USER_ID" NUMBER NOT NULL,
    "TITLE" VARCHAR2(200 BYTE) NOT NULL,
    "CONTENT" CLOB,
    "PUBLISHED_AT" TIMESTAMP(6)
);
ALTER TABLE "POSTS" ADD CONSTRAINT "SYS_C0000001" PRIMARY KEY (ID);
CREATE INDEX "IDX_USER_ID" ON "POSTS" ("USER_ID" ASC);

ALTER TABLE "POSTS" ADD CONSTRAINT "FK_USER" FOREIGN KEY ("USER_ID") REFERENCES "USERS" ("ID") ON DELETE CASCADE;
